import composeprobe.paint
import composeprobe.otherPaint
fun unsupported(s: composeprobe.Registry) { s.accept { paint(); otherPaint() } }

import composeprobe.execute
class Holder { fun hit() {} }
fun unsupported(s: composeprobe.Registry, h: Holder) { s.accept { execute { h.hit() } } }

import composeprobe.genericPayloadUse
import composeprobe.genericPayload
fun unsupported(s: composeprobe.Registry) { s.accept { genericPayloadUse(genericPayload()) } }
